// Server-side reads from the API for the web host's pages (Stage 07). Pages render on the server and
// ask the API with the browser's own cookies, host and IP (through lib/api/forward.ts), so the API
// applies exactly the rules a browser request would meet. Typed from the API's OpenAPI document
// (packages/contracts/src/api/schema.ts, regenerated by `npm run api:openapi`). Server only: client
// components cannot import it (eslint.config.mjs).
import { cache } from "react"
import { headers } from "next/headers"
import type { paths } from "@chaanavya/contracts/api/schema"
import { forwardToApi } from "@/lib/api/forward"

type Get<P extends keyof paths> = paths[P] extends { get: { responses: { 200: { content: { "application/json": infer T } } } } } ? T : never

export type Session = Get<"/api/v1/session">
export type SessionUser = NonNullable<Session["user"]>

/** An API answer: the parsed body and status. `ok` is false for any non-2xx status. */
export type ApiResult<T> = { ok: true; status: number; data: T } | { ok: false; status: number; error: unknown }

/** Browser headers the page request carried, as a GET to `path` on this host would carry them. */
async function asBrowserRequest(path: string) {
  const incoming = await headers()
  const forwarded = new Headers()
  for (const name of ["cookie", "host", "x-forwarded-host", "x-forwarded-for", "x-real-ip", "x-forwarded-proto", "user-agent", "x-correlation-id", "x-vercel-id"]) {
    const value = incoming.get(name)
    if (value !== null) forwarded.set(name, value)
  }
  const correlation = incoming.get("x-vercel-id")
  if (!forwarded.has("x-correlation-id") && correlation) forwarded.set("x-correlation-id", correlation)
  const host = incoming.get("x-forwarded-host") ?? incoming.get("host") ?? "localhost"
  return new Request(new URL(path, `http://${host}`), { headers: forwarded })
}

/** GET a web-host API path (for example "/api/admin/audit?limit=5") on behalf of the current visitor. The second argument only picks the response type from the OpenAPI paths. */
// eslint-disable-next-line @typescript-eslint/no-unused-vars
export async function apiGet<P extends keyof paths>(path: string, _typed?: P): Promise<ApiResult<Get<P>>> {
  const response = await forwardToApi(await asBrowserRequest(path))
  const body: unknown = await response.json().catch(() => null)
  return response.ok ? { ok: true, status: response.status, data: body as Get<P> } : { ok: false, status: response.status, error: body }
}

/** A readable message from an API error body (Stage 05/06 envelopes), for showing next to a form. */
export function problemOf(result: { ok: false; status: number; error: unknown }) {
  const error = (result.error as { error?: unknown } | null)?.error
  if (typeof error === "string") return error.replaceAll("_", " ")
  if (error && typeof error === "object" && typeof (error as { message?: unknown }).message === "string") return (error as { message: string }).message
  return `request failed (${result.status})`
}

/** The signed-in user for this page request, from the API. One lookup per request. */
export const currentSession = cache(async (): Promise<Session> => {
  const result = await apiGet("/api/session", "/api/v1/session")
  if (!result.ok) throw new Error(`session lookup failed with ${result.status}`)
  return result.data
})
